#!/usr/bin/env python3
"""Generates docs/experiments.md (20 experiments). Expected values for the validated experiments match tools/prayog_tools.py."""
from pathlib import Path
E = [
 # (title, topic, sensors, procedure, expected, validated)
 ("Cooling of hot water (Newton's law)", "Heat", "NTC temperature", ["Heat 200 ml water to about 85 C, pour into an insulated cup, place the NTC in the water.", "Log temperature every 30 s for 30 minutes; note the room temperature.", "Plot ln(T - T_room) against time."], "A straight line; slope = -k with k about 0.002 per s for a plain cup (the simulation recovers k to 5 %).", True),
 ("Melting ice: temperature plateau", "Heat", "NTC temperature", ["Crushed ice with a little water, NTC in the mixture, stir gently.", "Log for 20 minutes while it melts, then 10 minutes as it warms.", "Mark the plateau."], "Temperature stays near 0 C (within about 1.5 C of the NTC's accuracy) until the ice has melted, then rises.", False),
 ("Light intensity and distance", "Light", "LDR (lux)", ["Torch and LDR on a metre scale in a dark room.", "Log lux at 20, 30, ... 110 cm.", "Plot log(lux) against log(distance)."], "Slope about -2 (inverse-square law); the simulation recovers -2.00 within 4 %. Stray light makes it shallower: shield the LDR.", True),
 ("Loudness and distance", "Sound", "Microphone level", ["Speaker playing a steady tone, microphone at increasing distances.", "Log the mean level at 0.5, 1, 1.5, 2 m.", "Plot level against distance."], "Level falls roughly with the inverse of distance in a quiet open space; rooms add echoes and flatten the trend.", False),
 ("Speed of sound by echo", "Sound", "Ultrasonic distance", ["Ultrasonic module facing a wall at 0.3, 0.5, ... 2.1 m (tape measure).", "Log the echo time (microseconds) 10 times at each distance.", "Plot distance against echo time; c = 2 x slope."], "About 343 m/s at 20 C, rising 0.6 m/s per degree; simulation recovers 344 m/s within 2 %.", True),
 ("Pendulum: g from period and length", "Motion", "Photogate", ["String and steel ball, photogate at the lowest point.", "Lengths 0.3 to 1.0 m; log the period over 10 swings.", "Plot period squared against length; g = 4 pi squared / slope."], "g about 9.8 m/s2 (Hyderabad about 9.78); simulation recovers 9.82 within 2 %. Keep swing angles under 10 degrees.", True),
 ("Free fall: g from drop time", "Motion", "Two photogates", ["Drop a steel ball through two gates a known height apart.", "Heights 0.2 to 0.9 m.", "Plot height against time squared; g = 2 x slope."], "About 9.8 m/s2; needs timing to better than 1 ms (the photogate gives microseconds).", True),
 ("Speed of a trolley on a slope", "Motion", "Photogate", ["Card flag of known width (5 cm) on a trolley rolling down a slope.", "Log the beam-interruption time at three gate positions.", "Speed = width / time."], "Speed rises along the slope; compare with the energy calculation v = sqrt(2 g h) (smaller because of friction).", False),
 ("Ohm's law", "Electricity", "Voltage probes (2)", ["Resistor (47 ohm) with a 5 V supply through a variable series resistor.", "Measure voltage across the resistor and across a 1 ohm shunt (current = V/1).", "Plot V against I."], "Straight line through the origin; slope = resistance (47 ohm recovered within 3 %). Keep currents under 100 mA.", True),
 ("Series and parallel resistors", "Electricity", "Voltage probes", ["Build series and parallel combinations of 100 and 220 ohm.", "Measure the voltage drops.", "Compare with the calculated values."], "Series: voltages share in proportion to resistance; parallel: equal voltage.", False),
 ("Capacitor charging: RC time constant", "Electricity", "Voltage probe", ["Charge a 4.7 mF capacitor through 1 kohm from 5 V.", "Log voltage every 0.5 s for 15 s.", "Plot ln(5 - V) against time; tau = 1 / |slope|."], "Tau = R x C = 4.7 s; simulation recovers 4.72 s within 4 %.", True),
 ("Magnetic field of a bar magnet", "Magnetism", "Hall sensor", ["Magnet end-on to the Hall sensor, moved away in 5 mm steps.", "Log the field in mT.", "Plot log(B) against log(distance)."], "Field falls steeply: exponent about -3 on the axis (simulation recovers -3.07 within 7 %).", True),
 ("Soil drying curve", "Life science", "Soil moisture", ["Pot of wet soil in sunlight, sensor inserted.", "Log moisture % every 30 minutes for 2 days.", "Plot against time."], "Moisture decreases smoothly; faster in sun and wind. Compare shaded and sunny pots.", False),
 ("Day temperature and light log", "Earth science", "NTC + LDR", ["Place the sensors outdoors in shade.", "Log both every 5 minutes for 24 hours.", "Plot temperature and light together."], "Light peaks near noon; temperature peaks 2-3 hours later (thermal lag).", False),
 ("Colour and light reflection", "Light", "IR reflective sensor", ["Coloured paper sheets at 5 mm from the sensor.", "Log the reading for white, yellow, red, green, blue, black.", "Rank colours."], "White reflects most, black least; compare ranking with a phone-camera brightness estimate.", False),
 ("Conductivity of salt solutions", "Chemistry", "Conductivity probe", ["Distilled water plus 0, 0.5, ... 3 g salt per 100 ml.", "Dip the two-nail probe 2 cm each time; rinse between readings.", "Plot reading against concentration."], "Roughly linear at low concentration; simulation recovers the slope within 7 %. Probe polarisation: read quickly.", True),
 ("Human reaction time", "Biology", "Button + LED", ["LED lights after a random delay; press the button as fast as possible.", "Collect 40 trials per student.", "Mean and standard deviation; compare hands."], "About 0.2 s mean with 0.03-0.05 s spread; simulation recovers 0.21 s within 10 %.", True),
 ("Insulation test: three cups", "Heat", "3 x NTC", ["Same hot water in three cups: bare, wrapped in cloth, wrapped in foil.", "Log all three for 30 minutes.", "Compare the cooling constants k."], "Insulated cups have smaller k; rank the materials.", False),
 ("Water level by ultrasound (tank calibration)", "Mathematics and technology", "Ultrasonic distance", ["Sensor facing down from the top of a transparent container of known cross-section area.", "Add 200 ml of water at a time and log the distance to the surface.", "Plot volume against (empty distance minus measured distance)."], "A straight line whose slope equals the container's cross-section area; this is the principle of tank-level sensing.", False),
 ("Greenhouse jar model", "Earth science", "2 x NTC", ["Two identical jars in sunlight, one with a lid.", "Log both temperatures for 2 hours.", "Compare."], "The covered jar warms more and stays warmer; discuss the limits of the model.", False),
]
def main():
    L = ["# 20 experiments (Prayog kit)", "", "Topic areas only: **mapping to specific syllabus chapters must be verified by a teacher before printing.** Experiments marked VALIDATED have their analysis checked against simulated noisy data (`validation.md`). Hardware accuracy is not yet verified.", ""]
    for i, (t, topic, sens, proc, exp, val) in enumerate(E, 1):
        L += [f"## {i}. {t}", f"*Topic:* {topic}  |  *Sensors:* {sens}  |  *Analysis check:* {'VALIDATED' if val else 'not simulated'}", "", "**Procedure**"] + [f"{j}. {s}" for j, s in enumerate(proc, 1)]
        L += ["", f"**Expected result:** {exp}", "", "**Common errors:** loose connections, unshielded sensors, reading before values settle, wrong units. Repeat each measurement three times.", ""]
    Path(__file__).resolve().parent.parent.joinpath("docs", "experiments.md").write_text("\n".join(L) + "\n")
    print(f"{len(E)} experiments, {sum(1 for e in E if e[5])} validated by simulation")
main()
